export const SOURCE_REGISTRY = Object.freeze(Object.fromEntries(sourceRegistryDocument.sources.map(row => [row.source_id, { public: row.public === true, maximum_tier: row.maximum_pit_tier, source_url: row.source_url ?? null }])))

/* The requested tier is retained only as an audit field.  Authority is always
 * assigned by this reviewed registry; an unknown/custom import can never be
 * promoted by passing a more flattering CLI flag. */
export function assignPitTier({ source, requestedPitTier = null } = {}) {
  const sourceId = text(source, 'source')
  const registered = SOURCE_REGISTRY[sourceId]
  const assigned = registered?.maximum_tier || 'UNVERIFIED_DEVELOPMENT_ONLY'
  if (!PIT_TIERS.includes(assigned)) throw new Error(`source registry has invalid tier for ${sourceId}`)
  return { source_id: sourceId, requested_pit_tier: requestedPitTier, assigned_pit_tier: assigned, public_source: registered?.public === true, authority: registered ? 'REVIEWED_SOURCE_REGISTRY' : 'CUSTOM_IMPORT_DEVELOPMENT_ONLY' }
}

export function makeSourceReceipt({ source, sourceUrl = null, requestedPitTier = null, eventTimePolicy = 'completed_bar_event_time', availabilityTimePolicy = 'availability_time_required', captureTime = null, archiveChecksum = null, adapterSha256 = null, revisionPolicy = 'do_not_rewrite_prior_vintages' } = {}) {
  const assignment = assignPitTier({ source, requestedPitTier })
  const receipt = { schema: SOURCE_RECEIPT_SCHEMA, source_id: assignment.source_id, source: assignment.source_id, source_url: sourceUrl || SOURCE_REGISTRY[assignment.source_id]?.source_url || null, requested_pit_tier: requestedPitTier, assigned_pit_tier: assignment.assigned_pit_tier, event_time_policy: eventTimePolicy, availability_time_policy: availabilityTimePolicy, capture_time: captureTime, archive_checksum: archiveChecksum, adapter_sha256: adapterSha256, revision_policy: revisionPolicy, authority: assignment.authority }
  const result = withHash(receipt); validateContractSchema(result); return result
}

export function validateSourceReceipt(receipt, { phase = 'DEVELOPMENT' } = {}) {
  if (!receipt || receipt.schema !== SOURCE_RECEIPT_SCHEMA || receipt.content_sha256 !== ownHash(receipt)) throw new Error('source receipt hash/schema is invalid')
  validateContractSchema(receipt)
  const expected = assignPitTier({ source: receipt.source_id, requestedPitTier: receipt.requested_pit_tier })
  if (receipt.assigned_pit_tier !== expected.assigned_pit_tier) throw new Error('caller-supplied PIT tier cannot override reviewed source registry')
  if (receipt.authority !== expected.authority) throw new Error('source receipt authority is invalid')
  if (SOURCE_REGISTRY[receipt.source_id]?.source_url && receipt.source_url !== SOURCE_REGISTRY[receipt.source_id].source_url) throw new Error('source receipt URL is not bound to source registry')
  if (phase !== 'DEVELOPMENT') {
    if (expected.authority !== 'REVIEWED_SOURCE_REGISTRY') throw new Error('custom/unknown source receipts are development-only')
    if (!receipt.source_url && expected.public_source) throw new Error('load-bearing source receipt is missing source URL')
    if (!HASH_RE.test(String(receipt.archive_checksum || ''))) throw new Error('load-bearing source receipt is missing archive checksum')
    if (!HASH_RE.test(String(receipt.adapter_sha256 || ''))) throw new Error('load-bearing source receipt is missing adapter code hash')
    if (!receipt.capture_time || !Number.isFinite(Date.parse(receipt.capture_time))) throw new Error('load-bearing source receipt is missing capture time')
    if (!receipt.availability_time_policy || !receipt.event_time_policy) throw new Error('load-bearing source receipt is missing time policies')
  }
  return true
}

function futureLabelPath(value, path = '') {
  if (!value || typeof value !== 'object') return null
  for (const [key, child] of Object.entries(value)) { const childPath = path ? `${path}.${key}` : key; if (NO_LABEL_FIELDS.has(String(key).toLowerCase())) return childPath; const nested = futureLabelPath(child, childPath); if (nested) return nested }
  return null
}

