  return { valid: true, phase, coverage: coverageMatrix(featureRows, { assets: required }), label_coverage: coverageMatrix(labelRows, { assets: required }), feature_rows: featureRows.length, label_rows: labelRows.length, derivatives_history: featureRows.some(row => String(row.instrument_type || '').toLowerCase().includes('perp')) ? 'DECLARED_ONLY' : 'UNAVAILABLE_NOT_FABRICATED' }
