    const nestedRequired = [['feature_contract.series', precommit.feature_contract.series], ['experiment.evidence_phase', precommit.experiment.evidence_phase], ['experiment.ablation_role', precommit.experiment.ablation_role], ['experiment.required_assets', precommit.experiment.required_assets], ['experiment.grid', precommit.experiment.grid], ['experiment.acceptance.robust_stats', precommit.experiment.acceptance?.robust_stats], ['experiment.acceptance.plateau', precommit.experiment.acceptance?.plateau], ['experiment.acceptance.stress', precommit.experiment.acceptance?.stress], ['experiment.acceptance.portfolio', precommit.experiment.acceptance?.portfolio]]
    for (const [name, value] of nestedRequired) if (!hasValue(value)) throw new Error(`precommit missing required Stage-1 field: ${name}`)
    if (precommit.role_of_composite_score.toLowerCase().includes('select') || precommit.role_of_composite_score.toLowerCase().includes('threshold')) throw new Error('composite score selection is not allowed in CORE_PREMISE')
