  if (!instruments.length) throw new Error('precommit must declare at least one executable instrument')
  for (const row of instruments) { const spec = typeof row === 'string' ? { asset: row, instrument_type: row } : row; const rowAsset = String(spec.asset || '').toLowerCase(); if (!UNIVERSE.includes(rowAsset)) throw new Error(`instrument asset ${rowAsset || '?'} is outside the eight-asset universe`); const type = String(spec.instrument_type || spec.type || '').toLowerCase(); if (rowAsset === 'doge' || type.includes('doge')) throw new Error('DOGE is excluded'); if (!['spot', 'perpetual', 'dated_future', 'usd_m_linear_perpetual', 'usd_m_linear_future'].some(x => type === x || type.includes(x))) throw new Error(`unsupported executable instrument in precommit: ${type}`); if (spec.asset_class !== undefined && String(spec.asset_class).toLowerCase() !== 'crypto') throw new Error('only crypto instruments are executable'); if (spec.venue !== undefined && String(spec.venue).toLowerCase() !== 'binance') throw new Error('only Binance instruments are executable') }
