export function freezeNextPrecommit(value) { const precommit = clone(value); const retained = precommit.content_sha256; if (retained !== undefined) { validateNextPrecommit(precommit); return precommit } precommit.schema ||= 'strategy-precommit/1'; if (precommit.created_at === undefined) precommit.created_at = DETERMINISTIC_READINESS_TIME; precommit.content_sha256 = ownHash(precommit); validateNextPrecommit(precommit); return precommit }

